using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: default discriminator property renamed
        // from "Discriminator" to "$type". Preserve old name for existing documents.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change: id property no longer contains discriminator.
        // Existing documents use the old "EntityType|KeyValue" format.
        // Preserve old format so existing documents remain accessible.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Title { get; set; } = null!;
}

class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // EF Core 9 breaking change: synchronous I/O on the Cosmos DB provider
    // now throws. All queries and SaveChanges must use async equivalents.
    public async Task<List<Session>> GetSessionsAsync()
    {
        // Was: _db.Sessions.ToList()         — now throws
        return await _db.Sessions.ToListAsync();
    }

    public async Task SaveSessionAsync(Session session)
    {
        _db.Sessions.Add(session);
        // Was: _db.SaveChanges()             — now throws
        await _db.SaveChangesAsync();
    }
}

